def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Each outlined square is filled according to its interior size.
    fill_color = {3: 8, 5: 4, 7: 3}
    for top in range(h):
        for left in range(w):
            for size, color in fill_color.items():
                bottom, right = top + size + 1, left + size + 1
                if bottom >= h or right >= w:
                    continue
                if (all(grid[top][c] == 2 and grid[bottom][c] == 2
                        for c in range(left, right + 1)) and
                    all(grid[r][left] == 2 and grid[r][right] == 2
                        for r in range(top, bottom + 1))):
                    for r in range(top + 1, bottom):
                        for c in range(left + 1, right):
                            if grid[r][c] == 0:
                                out[r][c] = color
    return out
